1	/**
2	 * tasteEngine.js — 조미료 배합 맛 엔진 (리서치 보정판 v2)
3	 * --------------------------------------------------------------
4	 * 전부 순수 함수. 의존성 없음. 클라이언트/오프라인 동작.
5	 * 모든 맛 값은 0~10 스케일.
6	 *
7	 * 계수 근거 (RESEARCH.md 참조):
8	 *  [R1] 감칠맛 시너지: 글루탐산:이노신산 1:1 → 단독 대비 7~8배 (Umami Info Center;
9	 *       Yamaguchi 1979). 실제 음식 맥락에선 보수적으로 ×1.5 적용.
10	 *  [R2] 단맛은 가장 강한 suppressor이자 가장 덜 억제됨 (Green et al. 2010;
11	 *       Junge 2010, Physiol Behav). → 단맛 과잉 시 타 축 마스킹.
12	 *  [R3] 혼합 시 총 강도 ≈ 성분 합의 ~50% (Springer, Perceptual changes in
13	 *       taste mixtures). → 단순 합 금지, 균형/상호작용으로 보정.
14	 *  [R4] 짠–신 상호작용은 비단조: 저농도 상호 enhancement, 고농도 suppression
15	 *       (Keast & Breslin 2002). 소금이 신맛을 누름(salt depresses sourness).
16	 *  [R5] 짠맛은 쓴맛을 억제해 풍미를 해방 → 풍미 베이스 (Breslin & Beauchamp,
17	 *       Nature 1997). → 짠맛 베이스 로직의 근거.
18	 */
19	
20	export const TASTES = [
21	  { key: "salt",  label: "짠맛",   color: "#5B8DEF", sci: "Na⁺" },
22	  { key: "sweet", label: "단맛",   color: "#F2A0C4", sci: "당류" },
23	  { key: "sour",  label: "신맛",   color: "#E8C547", sci: "산도" },
24	  { key: "umami", label: "감칠맛", color: "#C77B3C", sci: "글루탐산" },
25	  { key: "spicy", label: "매운맛", color: "#E60044", sci: "캡사이신" },
26	];
27	
28	export const GOLD_ENTER = 78; // 존맛 존 진입 임계
29	export const GOLD_EXIT = 74;  // 이탈 임계 (히스테리시스 — 경계 깜빡임 방지)
30	
31	/**
32	 * 감칠맛 유효치 보정 [R1].
33	 * combo에 umamiSynergy(0~1: 글루탐산계 × 이노신산계 동시 존재도)가 있으면
34	 * 감칠맛 체감을 최대 1.5배까지 끌어올린다.
35	 * 예) 간장(글루탐산) + 멸치·가다랑어·고기(이노신산) → synergy 높음.
36	 */
37	export function effectiveUmami(umami, synergy = 0) {
38	  return Math.min(10, umami * (1 + 0.5 * Math.max(0, Math.min(1, synergy))));
39	}
40	
41	/**
42	 * 존맛 지수 0~100.
43	 * @param {{salt,sweet,sour,umami,spicy}} t  맛 벡터 (0~10)
44	 * @param {number} synergy  감칠맛 시너지도 0~1 (선택)
45	 */
46	export function deliciousness(t, synergy = 0) {
47	  const { salt, sweet, sour, spicy } = t;
48	  const umami = effectiveUmami(t.umami, synergy); // [R1]
49	
50	  // 1) 짠맛 베이스(간) [R5] — 3~7 스위트스팟
51	  let saltBase;
52	  if (salt < 3) saltBase = salt * 8;
53	  else if (salt <= 7) saltBase = 24;
54	  else saltBase = 24 - (salt - 7) * 6;
55	
56	  // 2) 단짠 시너지 — 적정 비율에서만. 과하면 "clashing"이라 보너스 없음 [R3]
57	  const sweetSalt = (salt >= 3 && sweet >= 2 && sweet <= 6) ? 18 : 0;
58	
59	  // 3) 감칠맛 보너스 (유효 감칠맛 기준) [R1]
60	  const umamiBonus = Math.min(umami, 8) * 3.2;
61	
62	  // 3b) 감칠 시너지 직접 보너스 [R1] — 두 감칠맛원 동시 존재 시 가산
63	  const synergyBonus = Math.max(0, Math.min(1, synergy)) * 9;
64	
65	  // 4) 신맛 밸런스 [R4] — 약간이 둥글게, 과하면 날카로움
66	  let sourBalance;
67	  if (sour <= 4) sourBalance = sour * 3;
68	  else sourBalance = 12 - (sour - 4) * 4;
69	
70	  // 5) 매운맛 마스킹 페널티 — 과하면 다른 맛 가림
71	  const spicyPenalty = spicy > 7 ? -(spicy - 7) * 6 : 0;
72	
73	  // 5b) 단맛 마스킹 페널티 [R2] — 단맛은 강력한 suppressor.
74	  //     단맛이 과하면(>7) 짠·감칠·신의 체감을 깎는다.
75	  const sweetMask = sweet > 7 ? -(sweet - 7) * 5 : 0;
76	
77	  // 6) 균형 페널티 — 한 축만 튀면 감점 (표준편차)
78	  const vals = [salt, sweet, sour, umami, spicy];
79	  const mean = vals.reduce((a, b) => a + b, 0) / 5;
80	  const sd = Math.sqrt(vals.reduce((a, b) => a + (b - mean) ** 2, 0) / 5);
81	  const balancePenalty = sd > 3.2 ? -(sd - 3.2) * 7 : 0;
82	
83	  // 7) 무맛 페널티
84	  const flatPenalty = mean < 1.5 ? -20 : 0;
85	
86	  const raw = saltBase + sweetSalt + umamiBonus + synergyBonus + sourBalance
87	            + spicyPenalty + sweetMask + balancePenalty + flatPenalty;
88	  return Math.max(0, Math.min(100, Math.round(raw)));
89	}
90	
91	/** 셰프 미강 진단 — 우선순위 룰 (첫 매칭 반환) */
92	export function chefVerdict(t, score) {
93	  const { salt, sweet, sour, umami, spicy } = t;
94	  if (score >= GOLD_ENTER)
95	    return { mood: "gold", title: "완성입니다.",
96	      body: "짠맛이 중심을 잡고 그 위로 맛이 층층이 쌓였습니다. 무엇에 넣어도 실패하지 않습니다. 그대로 가세요." };
97	  if (salt < 2.5)
98	    return { mood: "fix", title: "간이 빠졌습니다.",
99	      body: "모든 맛의 토대는 짠맛입니다. 간장·소금 계열을 조금 더. 베이스가 서야 나머지가 살아납니다." };
100	  if (salt > 8)
101	    return { mood: "fix", title: "너무 짭니다.",
102	      body: "혀가 짠맛에 막혀 다른 맛을 못 느낍니다. 물이나 단맛으로 풀어주세요." };
103	  if (sweet > 8)
104	    return { mood: "fix", title: "단맛이 다 덮었습니다.",
105	      body: "단맛은 다른 맛을 가장 강하게 누릅니다. 한 단계만 내리면 짠맛·감칠맛이 살아납니다." };
106	  if (spicy > 8)
107	    return { mood: "fix", title: "매운맛이 다 덮었습니다.",
108	      body: "캡사이신이 강하면 감칠맛·단맛이 가려집니다. 매운맛을 한 단계만 내려보시죠." };
109	  if (sour > 7)
110	    return { mood: "fix", title: "신맛이 앞섭니다.",
111	      body: "산도가 높으면 날카로워집니다. 단맛을 조금 올려 균형을 잡으면 둥글어집니다." };
112	  if (umami < 2)
113	    return { mood: "fix", title: "맛이 얕습니다.",
114	      body: "감칠맛이 부족합니다. 간장·굴소스·발효장류로 깊이를 한 겹 더하세요." };
115	  if (salt >= 3 && sweet < 1.5)
116	    return { mood: "tune", title: "조금 단조롭습니다.",
117	      body: "짠맛은 잡혔으나 단맛이 받쳐주지 않습니다. 단짠의 대비가 식욕을 만듭니다. 설탕·물엿을 살짝." };
118	  return { mood: "tune", title: "거의 왔습니다.",
119	    body: "방향은 맞습니다. 한두 축만 미세하게 조정하면 황금 균형에 도달합니다." };
120	}
121	
122	/** 맛 벡터 → 어울리는 요리 */
123	export function matchDish(t) {
124	  const { salt, sweet, sour, umami, spicy } = t;
125	  if (spicy >= 6 && salt >= 4) return "제육·매운 볶음 양념";
126	  if (sour >= 5 && sweet >= 4) return "새콤달콤 무침·초장";
127	  if (umami >= 6 && sweet >= 4 && spicy < 4) return "불고기·갈비 양념";
128	  if (umami >= 6 && salt >= 5) return "감칠 볶음·볶음밥";
129	  if (sweet >= 5 && sour >= 3) return "탕수·디핑 소스";
130	  if (salt >= 4 && umami >= 4) return "기본 간장 베이스 조림";
131	  return "범용 만능장 (간 맞추는 중)";
132	}
133	
134	/** 현재 맛에 가장 가까운 시판 조합 n개 (유클리드 거리) */
135	export function nearestCombos(t, combos, n = 2) {
136	  const dist = (v) =>
137	    Math.sqrt(TASTES.reduce((a, { key }) => a + (t[key] - v[key]) ** 2, 0));
138	  return [...combos].sort((a, b) => dist(a.v) - dist(b.v)).slice(0, n);
139	}
140	
141	/**
142	 * (v3 예고) 역최적화: 목표 맛 벡터 → 황금 슬라이더값 제안.
143	 * 목표 distance 최소 + deliciousness 최대를 만족하는 벡터를 좌표하강으로 탐색.
144	 * "단짠하게!" 버튼 → 프리셋 목표 벡터 주입 후 호출.
145	 */
146	export function suggestGolden(target) {
147	  let best = { ...target }, bestScore = deliciousness(best);
148	  for (let iter = 0; iter < 60; iter++) {
149	    for (const { key } of TASTES) {
150	      for (const d of [-0.5, 0.5]) {
151	        const cand = { ...best, [key]: Math.max(0, Math.min(10, best[key] + d)) };
152	        const s = deliciousness(cand);
153	        if (s > bestScore) { best = cand; bestScore = s; }
154	      }
155	    }
156	  }
157	  return { vector: best, score: bestScore };
158	}
