import React, { useState, useMemo, useEffect } from "react";
import {
  Radar, RadarChart, PolarGrid, PolarAngleAxis, ResponsiveContainer,
} from "recharts";

/* ────────────────────────────────────────────────────────────
   맛 5축 정의 + 컬러 시그니처
   ──────────────────────────────────────────────────────────── */
const TASTES = [
  { key: "salt",  label: "짠맛",   color: "#5B8DEF", sci: "Na⁺" },
  { key: "sweet", label: "단맛",   color: "#F2A0C4", sci: "당류" },
  { key: "sour",  label: "신맛",   color: "#E8C547", sci: "산도" },
  { key: "umami", label: "감칠맛", color: "#C77B3C", sci: "글루탐산" },
  { key: "spicy", label: "매운맛", color: "#E60044", sci: "캡사이신" },
];

/* ────────────────────────────────────────────────────────────
   시판 기성품 조합 DB  (맛 벡터: 0~10)
   v1은 브랜드명 대신 '제품군'으로 추상화
   ──────────────────────────────────────────────────────────── */
const PRODUCT_COMBOS = [
  { name: "만능간장 + 굴소스",        ratio: "2 : 1",       dish: "만능 볶음장",   v: { salt: 8, sweet: 4, sour: 1, umami: 9, spicy: 0 } },
  { name: "간장 + 설탕 + 다진마늘",    ratio: "3 : 1 : 0.5", dish: "불고기 양념",   v: { salt: 7, sweet: 6, sour: 1, umami: 6, spicy: 1 } },
  { name: "고추장 + 물엿 + 식초",      ratio: "2 : 1 : 1",   dish: "초고추장",      v: { salt: 5, sweet: 7, sour: 6, umami: 5, spicy: 5 } },
  { name: "된장 + 고추장",            ratio: "2 : 1",       dish: "쌈장 베이스",    v: { salt: 7, sweet: 3, sour: 1, umami: 8, spicy: 4 } },
  { name: "굴소스 + 스리라차",         ratio: "2 : 1",       dish: "매콤 볶음",      v: { salt: 7, sweet: 3, sour: 2, umami: 8, spicy: 7 } },
  { name: "마요 + 스리라차 + 꿀",      ratio: "3 : 1 : 0.5", dish: "마약 디핑소스",  v: { salt: 3, sweet: 5, sour: 3, umami: 3, spicy: 6 } },
  { name: "간장 + 식초 + 설탕",        ratio: "2 : 2 : 1",   dish: "새콤달콤 무침",  v: { salt: 6, sweet: 6, sour: 7, umami: 4, spicy: 1 } },
  { name: "케첩 + 마요",              ratio: "1 : 1",       dish: "분식 소스",      v: { salt: 4, sweet: 6, sour: 4, umami: 3, spicy: 1 } },
  { name: "고추장 + 간장 + 설탕 + 고춧가루", ratio: "2:1:1:0.5", dish: "제육 양념",  v: { salt: 7, sweet: 6, sour: 1, umami: 6, spicy: 8 } },
  { name: "굴소스 + 간장 + 설탕",      ratio: "2 : 1 : 1",   dish: "감칠 볶음밥",    v: { salt: 8, sweet: 5, sour: 1, umami: 9, spicy: 0 } },
];

/* ────────────────────────────────────────────────────────────
   존맛 스코어 엔진 (룰베이스 + 상호작용 항)
   - 짠맛 베이스가 간을 잡고
   - 단짠 시너지, 감칠맛 보너스, 신맛 밸런스
   - 한 축 과잉 / 매운맛 마스킹 페널티
   ──────────────────────────────────────────────────────────── */
function deliciousness({ salt, sweet, sour, umami, spicy }) {
  // 1) 짠맛 베이스 (간) — 3~7이 스위트스팟, 0이면 싱거움, 과하면 짜다
  let saltBase;
  if (salt < 3) saltBase = salt * 7;            // 0~21
  else if (salt <= 7) saltBase = 22;            // 이상 구간
  else saltBase = 22 - (salt - 7) * 6;          // 과염 페널티

  // 2) 단짠 시너지 — 둘 다 적당히 있으면 보너스
  const sweetSalt = (salt >= 3 && sweet >= 2 && sweet <= 6) ? 16 : 0;

  // 3) 감칠맛 — 깊이. 거의 항상 플러스 (상한 7)
  const umamiBonus = Math.min(umami, 7) * 3;    // 0~21

  // 4) 신맛 — 약간이 전체를 둥글게, 과하면 시다
  let sourBalance;
  if (sour <= 4) sourBalance = sour * 3;         // 0~12
  else sourBalance = 12 - (sour - 4) * 4;        // 과산 페널티

  // 5) 매운맛 — 과하면 다른 맛 마스킹
  const spicyPenalty = spicy > 7 ? -(spicy - 7) * 6 : 0;

  // 6) 균형 페널티 — 한 축만 튀면 감점 (표준편차 기반)
  const vals = [salt, sweet, sour, umami, spicy];
  const mean = vals.reduce((a, b) => a + b, 0) / 5;
  const sd = Math.sqrt(vals.reduce((a, b) => a + (b - mean) ** 2, 0) / 5);
  const balancePenalty = sd > 3.2 ? -(sd - 3.2) * 7 : 0;

  // 7) 전부 0 근처면 무맛
  const flatPenalty = mean < 1.5 ? -20 : 0;

  const raw = saltBase + sweetSalt + umamiBonus + sourBalance
            + spicyPenalty + balancePenalty + flatPenalty;
  return Math.max(0, Math.min(100, Math.round(raw)));
}

/* 현재 맛 → 셰프 진단 멘트 (룰베이스 생성) */
function chefVerdict(t, score) {
  const { salt, sweet, sour, umami, spicy } = t;
  if (score >= 78) {
    return {
      mood: "gold",
      title: "완성입니다.",
      body: "짠맛이 중심을 잡고 그 위로 맛이 층층이 쌓였습니다. 이 균형이면 무엇에 넣어도 실패하지 않습니다. 그대로 가세요.",
    };
  }
  // 진단 우선순위
  if (salt < 2.5)
    return { mood: "fix", title: "간이 빠졌습니다.", body: "모든 맛의 토대는 짠맛입니다. 간장이나 소금 계열을 조금 더. 베이스가 서야 나머지가 살아납니다." };
  if (salt > 8)
    return { mood: "fix", title: "너무 짭니다.", body: "혀가 짠맛에 막혀 다른 맛을 못 느낍니다. 물이나 단맛으로 풀어주세요." };
  if (spicy > 8)
    return { mood: "fix", title: "매운맛이 다 덮었습니다.", body: "캡사이신이 강하면 감칠맛·단맛이 가려집니다. 매운맛을 한 단계만 내려보시죠." };
  if (sour > 7)
    return { mood: "fix", title: "신맛이 앞섭니다.", body: "산도가 높으면 날카로워집니다. 단맛을 조금 올려 균형을 잡으면 둥글어집니다." };
  if (umami < 2)
    return { mood: "fix", title: "맛이 얕습니다.", body: "감칠맛이 부족합니다. 간장·굴소스·발효장류로 깊이를 한 겹 더하세요." };
  if (salt >= 3 && sweet < 1.5)
    return { mood: "tune", title: "조금 단조롭습니다.", body: "짠맛은 잡혔으나 단맛이 받쳐주지 않습니다. 단짠의 대비가 식욕을 만듭니다. 설탕·물엿을 살짝." };
  return { mood: "tune", title: "거의 왔습니다.", body: "방향은 맞습니다. 한두 축만 미세하게 조정하면 황금 균형에 도달합니다." };
}

/* 맛 벡터 → 어울리는 요리 매칭 */
function matchDish(t) {
  const { salt, sweet, sour, umami, spicy } = t;
  if (spicy >= 6 && salt >= 4) return "제육·매운 볶음 양념";
  if (sour >= 5 && sweet >= 4) return "새콤달콤 무침·초장";
  if (umami >= 6 && sweet >= 4 && spicy < 4) return "불고기·갈비 양념";
  if (umami >= 6 && salt >= 5) return "감칠 볶음·볶음밥";
  if (sweet >= 5 && sour >= 3) return "탕수·디핑 소스";
  if (salt >= 4 && umami >= 4) return "기본 간장 베이스 조림";
  return "범용 만능장 (간 맞추는 중)";
}

/* 현재 맛에 가장 가까운 시판 조합 추천 */
function nearestCombos(t, n = 2) {
  const dist = (v) =>
    Math.sqrt(TASTES.reduce((a, { key }) => a + (t[key] - v[key]) ** 2, 0));
  return [...PRODUCT_COMBOS].sort((a, b) => dist(a.v) - dist(b.v)).slice(0, n);
}

/* ────────────────────────────────────────────────────────────
   슬라이더 컴포넌트
   ──────────────────────────────────────────────────────────── */
function TasteSlider({ taste, value, onChange }) {
  return (
    <div style={{ marginBottom: 14 }}>
      <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", marginBottom: 5 }}>
        <span style={{ display: "flex", alignItems: "center", gap: 7 }}>
          <span style={{ width: 9, height: 9, borderRadius: "50%", background: taste.color, boxShadow: `0 0 8px ${taste.color}` }} />
          <span style={{ fontWeight: 700, fontSize: 14, color: "#F0EDE6" }}>{taste.label}</span>
          <span style={{ fontFamily: "'Space Mono', monospace", fontSize: 9, color: "#6F7972", letterSpacing: ".3px" }}>{taste.sci}</span>
        </span>
        <span style={{ fontFamily: "'Space Mono', monospace", fontSize: 13, fontWeight: 700, color: taste.color, minWidth: 26, textAlign: "right" }}>
          {value.toFixed(1)}
        </span>
      </div>
      <input
        type="range" min={0} max={10} step={0.5} value={value}
        onChange={(e) => onChange(parseFloat(e.target.value))}
        style={{ width: "100%", accentColor: taste.color, height: 4, cursor: "pointer" }}
      />
    </div>
  );
}

/* ────────────────────────────────────────────────────────────
   메인
   ──────────────────────────────────────────────────────────── */
export default function TasteMixer() {
  const [t, setT] = useState({ salt: 6, sweet: 4, sour: 2, umami: 7, spicy: 1 });
  const set = (key) => (val) => setT((p) => ({ ...p, [key]: val }));

  const score = useMemo(() => deliciousness(t), [t]);
  const verdict = useMemo(() => chefVerdict(t, score), [t, score]);
  const dish = useMemo(() => matchDish(t), [t]);
  const combos = useMemo(() => nearestCombos(t), [t]);
  const isGold = score >= 78;

  const radarData = TASTES.map((x) => ({ taste: x.label, v: t[x.key], full: 10 }));

  // 스코어에 따른 게이지 컬러
  const gauge = score >= 78 ? "#FFD23F" : score >= 55 ? "#9CCB6A" : score >= 30 ? "#E8C547" : "#C96A5E";

  return (
    <div style={{
      minHeight: "100vh", background: "#0F1411",
      display: "flex", justifyContent: "center", alignItems: "flex-start",
      padding: "24px 12px", fontFamily: "'Noto Sans KR', sans-serif",
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Noto+Sans+KR:wght@400;500;700&family=Space+Mono:wght@400;700&display=swap');
        @keyframes goldpulse { 0%,100%{opacity:.55} 50%{opacity:1} }
        input[type=range]{ -webkit-appearance:none; appearance:none; background:#2A332E; border-radius:99px; }
        input[type=range]::-webkit-slider-thumb{ -webkit-appearance:none; width:18px; height:18px; border-radius:50%; background:#F0EDE6; cursor:pointer; box-shadow:0 1px 4px rgba(0,0,0,.5); }
      `}</style>

      {/* 모바일 프레임 */}
      <div style={{
        width: "100%", maxWidth: 390, background: "#161D19",
        borderRadius: 28, overflow: "hidden",
        border: "1px solid #232C27",
        boxShadow: isGold
          ? "0 0 0 1px rgba(255,210,63,.35), 0 24px 60px -20px rgba(255,210,63,.25)"
          : "0 24px 60px -24px rgba(0,0,0,.8)",
        transition: "box-shadow .5s ease",
      }}>
        {/* 헤더 */}
        <div style={{ padding: "20px 20px 14px", borderBottom: "1px solid #232C27" }}>
          <div style={{ fontFamily: "'Space Mono', monospace", fontSize: 10, letterSpacing: "2px", color: "#6F7972", textTransform: "uppercase" }}>
            Taste Engine · 배합 시뮬레이터
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 11, marginTop: 9 }}>
            <div style={{
              width: 38, height: 38, borderRadius: "50%", flexShrink: 0,
              background: "linear-gradient(135deg,#C77B3C,#7A4A22)",
              display: "flex", alignItems: "center", justifyContent: "center",
              fontFamily: "'Fraunces', serif", fontWeight: 700, fontSize: 18, color: "#FFF3E4",
            }}>味</div>
            <div>
              <div style={{ fontFamily: "'Fraunces', serif", fontSize: 19, fontWeight: 600, color: "#F0EDE6", lineHeight: 1.1 }}>
                셰프 미강 <span style={{ fontSize: 12, color: "#8A938C", fontWeight: 500 }}>味江</span>
              </div>
              <div style={{ fontSize: 11, color: "#8A938C" }}>당신의 혀를 위한 균형 설계자</div>
            </div>
          </div>
        </div>

        {/* 레이더 + 스코어 */}
        <div style={{ position: "relative", padding: "6px 8px 0" }}>
          {isGold && (
            <div style={{
              position: "absolute", inset: "6px 8px 0", borderRadius: 20,
              background: "radial-gradient(circle at 50% 42%, rgba(255,210,63,.18), transparent 62%)",
              animation: "goldpulse 2.4s ease-in-out infinite", pointerEvents: "none",
            }} />
          )}
          <ResponsiveContainer width="100%" height={230}>
            <RadarChart data={radarData} outerRadius="72%">
              <PolarGrid stroke="#2C352F" />
              <PolarAngleAxis
                dataKey="taste"
                tick={{ fill: "#B9C0BA", fontSize: 12, fontWeight: 700 }}
              />
              <Radar dataKey="full" stroke="none" fill="#1E2722" fillOpacity={0.5} />
              <Radar
                dataKey="v"
                stroke={isGold ? "#FFD23F" : "#C77B3C"}
                strokeWidth={2}
                fill={isGold ? "#FFD23F" : "#C77B3C"}
                fillOpacity={isGold ? 0.4 : 0.28}
                isAnimationActive={true}
                animationDuration={300}
              />
            </RadarChart>
          </ResponsiveContainer>

          {/* 존맛 스코어 */}
          <div style={{ textAlign: "center", marginTop: -6, marginBottom: 4 }}>
            <span style={{ fontFamily: "'Space Mono', monospace", fontSize: 44, fontWeight: 700, color: gauge, lineHeight: 1 }}>
              {score}
            </span>
            <span style={{ fontFamily: "'Space Mono', monospace", fontSize: 14, color: "#6F7972" }}> / 100</span>
            <div style={{ fontSize: 11, letterSpacing: "1px", color: "#8A938C", marginTop: 2 }}>
              {isGold ? "★ 존맛 존 GOLDEN ZONE ★" : "존맛 지수"}
            </div>
          </div>
          {/* 게이지 바 */}
          <div style={{ height: 6, background: "#222B26", borderRadius: 99, margin: "0 4px 12px", overflow: "hidden" }}>
            <div style={{ width: `${score}%`, height: "100%", background: gauge, borderRadius: 99, transition: "width .3s ease, background .3s" }} />
          </div>
        </div>

        {/* 셰프 진단 카드 */}
        <div style={{ margin: "0 16px 14px", padding: "13px 15px", borderRadius: 14,
          background: verdict.mood === "gold" ? "rgba(255,210,63,.09)" : "#1B2420",
          border: `1px solid ${verdict.mood === "gold" ? "rgba(255,210,63,.4)" : "#2A332E"}` }}>
          <div style={{ fontFamily: "'Fraunces', serif", fontSize: 16, fontWeight: 600,
            color: verdict.mood === "gold" ? "#FFD23F" : "#F0EDE6", marginBottom: 4 }}>
            “{verdict.title}”
          </div>
          <div style={{ fontSize: 13, lineHeight: 1.6, color: "#B9C0BA" }}>{verdict.body}</div>
        </div>

        {/* 슬라이더 (조절좌) */}
        <div style={{ padding: "0 18px 6px" }}>
          <div style={{ fontFamily: "'Space Mono', monospace", fontSize: 10, letterSpacing: "1.5px", color: "#6F7972", marginBottom: 10, textTransform: "uppercase" }}>
            조절좌 — 맛을 직접 빚어보세요
          </div>
          {TASTES.map((x) => (
            <TasteSlider key={x.key} taste={x} value={t[x.key]} onChange={set(x.key)} />
