const chk=(name,cond,info='')=>{ (cond?pass++:fail++); console.log((cond?'✓':'✗ FAIL')+' '+name+(info?'  → '+info:'')); };
const g = (r,name)=>{ const it=r.ingredients.find(i=>i.name===name); return it?it.amountG:null; };
const inrange=(v,lo,hi)=> v!=null && v>=lo && v<=hi;

// Test 1: 아이 반찬 300g 아이용 달달짭짤 (템플릿)
