chk('T1 올리고당 6~12g', inrange(g(r1,'올리고당/물엿'),6,12), g(r1,'올리고당/물엿')?.toFixed(1));
chk('T1 버터 8~15g', inrange(g(r1,'버터'),8,15), g(r1,'버터')?.toFixed(1));
chk('T1 산미 거의 없음', !r1.ingredients.some(i=>['식초','레몬즙'].includes(i.name)));
chk('T1 매운재료 없음', !r1.ingredients.some(i=>['고추장','고춧가루','칠리소스'].includes(i.name)));

