const prof = Object.assign({}, cat, style.over||{});
const rec = style.rec;
const targets = {
  salt: w*mid(prof.saltPct)/100 * intMul("salt",mode) * (style.saltMultiplier||1),
  sweet:w*mid(prof.sweetPct)/100* intMul("sweet",mode)* (style.sweetMultiplier||1),
  acid: w*mid(prof.acidPct)/100 * intMul("acid",mode) * (style.acidMultiplier||1),
  fat:  w*mid(prof.fatPct)/100  * intMul("fat",mode)  * (style.fatMultiplier||1)
};
const FIELD={salt:"saltEq",sweet:"sweetEq",acid:"acidEq",fat:"fatEq"};
const AROMA=new Set(["garlic","ginger","green_onion","sesame","herbs","pepper","fried_garlic","fried_onion"]);
const primaryAxis=id=>{ const c=C(id); const a=[["salt",c.saltEq||0],["sweet",c.sweetEq||0],["acid",c.acidEq||0],["fat",c.fatEq||0]].sort((x,y)=>y[1]-x[1]); return a[0][1]>0?a[0][0]:null; };
const timingFor=(id,ax)=> ax==="fat" ? ((id==="butter"||id==="sesame_oil")?"finish":"early") : ax==="acid" ? "finish" : "middle";
ings = [];
const add=(id,g,t)=>{ if(g>0){ const c=C(id); ings.push({id,name:c.name,amountG:g,timing:t,density:c.density}); } };

// 1) 향채(기름향) — early
if(rec.includes("garlic")) add("garlic", w*0.013, "early");
if(rec.includes("ginger")) add("ginger", w*0.004, "early");
if(rec.includes("green_onion")) add("green_onion", w*0.02, "early");
if(rec.includes("fried_garlic")) add("fried_garlic", w*0.02, "early");
if(rec.includes("fried_onion")) add("fried_onion", w*0.02, "early");

// 2) 측정 가능한 맛 축 배분 (주재료 70% + 보조재료 30% 균등) — 추천 조합을 모두 노출
for(const ax of ["fat","salt","sweet","acid"]){
  let prov = rec.filter(id=>!AROMA.has(id) && (C(id)[FIELD[ax]]||0)>0 && primaryAxis(id)===ax);
  if(ax==="salt" && !prov.length) prov=["soy_sauce"]; // 간은 반드시
  const tgt = targets[ax];
  if(!prov.length || tgt<=0) continue;
  prov.sort((a,b)=> (C(b)[FIELD[ax]]||0)-(C(a)[FIELD[ax]]||0));
  const prim=prov[0], secs=prov.slice(1);
  add(prim, (secs.length?0.7:1)*tgt / C(prim)[FIELD[ax]], timingFor(prim,ax));
  secs.forEach(id=> add(id, (0.3*tgt/secs.length) / C(id)[FIELD[ax]], timingFor(id,ax)));
}

// 3) 측정축 없는 향/감칠/매콤 보조
if(rec.includes("dashi") && prof.umami>=4) add("dashi", w*0.05, "middle");
if(rec.includes("chili_powder")) add("chili_powder", w*0.008*intMul("spice",mode), "middle");
if(rec.includes("sesame")) add("sesame", w*0.01, "finish");
if(rec.includes("herbs")) add("herbs", Math.max(0.3,w*0.004), "finish");
if(rec.includes("pepper")) add("pepper", Math.max(0.2,w*0.001), "finish");
if(rec.includes("starch_water")) add("starch_water", w*0.06, "finish");

const order={early:0, middle:1, finish:2};
ings.sort((a,b)=> order[a.timing]-order[b.timing]);
steps = buildSteps(ings);

