    e.salt+=(c.saltEq||0)*g; e.sweet+=(c.sweetEq||0)*g; e.acid+=(c.acidEq||0)*g; e.fat+=(c.fatEq||0)*g;
    e.umami=Math.max(e.umami,c.umami||0); e.spice=Math.max(e.spice,c.spice||0);
    if((c.umami||0)>=3) e.umamiCount++;
  });
  return e;
}
function tasteAxis(w, eq, cat, style){
