    spice: clamp(eq.spice,0,5)
  };
}
/* 존맛 지수: 카테고리 목표 적합도(fit) + 맛 균형 휴리스틱(delight) 블렌드 */
function scoreZon(w, eq, prof, ings){
  const saltD = clamp(eq.salt/w*100/0.2,0,10);   // 약 1% 염도 → 5
  const sweetD= clamp(eq.sweet/w*100/1.0,0,10);
  const sourD = clamp(eq.acid/w*100/1.0,0,10);
  const umamiD= clamp(prof.umami*2,0,10);
  const spiceD= clamp(eq.spice*2,0,10);
  const syn = clamp((eq.umamiCount-1)*0.35,0,0.7);   // 두 감칠맛원↑ → 시너지 [R1]
  const delight = deliciousness({salt:saltD,sweet:sweetD,sour:sourD,umami:umamiD,spicy:spiceD}, syn);
  let pen=0;
  [["salt","saltPct"],["sweet","sweetPct"],["acid","acidPct"],["fat","fatPct"]].forEach(([k,pk])=>{
    const pct = eq[k]/w*100, lo=prof[pk][0], hi=prof[pk][1];
    if(pct<lo) pen += Math.min(22,(lo-pct)/Math.max(lo,0.5)*22);
    else if(pct>hi) pen += Math.min(22,(pct-hi)/Math.max(hi,1)*22);
  });
  const fit = Math.max(0, Math.round(100-pen));
  const score = clamp(Math.round(0.45*fit + 0.55*delight),0,100);
  return {score, fit, delight, gold:score>=GOLD_ENTER};
}

