  let salt=0,sweet=0,acid=0,fat=0,umami=0,spice=0;
  ings.forEach(it=>{ const c=C(it.id); const g=it.amountG;
    salt += (c.saltEq||0)*g; sweet += (c.sweetEq||0)*g; acid += (c.acidEq||0)*g; fat += (c.fatEq||0)*g;
    umami = Math.max(umami, c.umami||0); spice = Math.max(spice, c.spice||0);
  });
  const prof = Object.assign({}, cat, style.over||{});
  return {
    salt: clamp(Math.round((salt/w*100)/1.4*5),0,5),
    sweet: clamp(Math.round((sweet/w*100)/8*5),0,5),
    acid: clamp(Math.round((acid/w*100)/8*5),0,5),
    fat: clamp(Math.round((fat/w*100)/20*5),0,5),
    umami: clamp(Math.round(prof.umami),0,5),
    spice: clamp(spice,0,5)
  };
}

