import fs from 'fs';
const html=fs.readFileSync('요똥을_위한_전자혀.html','utf8');
const script=html.split('<script>')[1].split('</script>')[0];
const body=script.slice(script.indexOf('"use strict"'));
const engine=body.slice(0, body.indexOf('PART D. UI')).replace(/\/\*[^*]*$/,'');
fs.writeFileSync('_e.mjs', engine+'\nexport {calcRecipe, PRODUCT_COMBOS, COND};');
const E=await import('./_e.mjs');
const names=r=>r.ingredients.map(i=>i.name).join(', ');
console.log('=== 다시다/연두 등장 확인 ===');
for(const [n,cat,st] of [['찌개','stew','basic_home'],['조림','braise','basic_home'],['백종원볶음','stir_fry','baek_jongwon'],['최강록','stir_fry','choi_kangrok'],['고든램지(제외)','grill','gordon_ramsay'],['로제','stir_fry','trendy_rose']]){
  const r=E.calcRecipe({categoryId:cat,foodWeightG:300,stylePresetId:st,intensity:'normal'});
  const has=r.ingredients.find(i=>['다시다','연두'].includes(i.name));
  console.log('  '+n+': '+(has?('💧 '+has.name+' '+has.amountG.toFixed(1)+'g'):'(없음)')+'  | '+names(r));
}
console.log('\n=== PRD 회귀 테스트 ===');
const g=(r,nm)=>{const i=r.ingredients.find(x=>x.name===nm);return i?i.amountG:null;};
const ir=(v,lo,hi)=>v!=null&&v>=lo&&v<=hi;
let r1=E.calcRecipe({categoryId:'kids_side',foodWeightG:300,stylePresetId:'kids_sweet_savory',intensity:'normal'});
console.log('  T1 아이용(템플릿,부스터X): 간장15='+(g(r1,'간장')===15)+' 다시다없음='+(!r1.ingredients.some(i=>i.name==='다시다')));
let r2=E.calcRecipe({categoryId:'stir_fry',foodWeightG:500,stylePresetId:'trendy_rose',intensity:'normal'});
console.log('  T2 로제: 고추장/케첩/우유/치즈='+['고추장','케첩','우유/크림','치즈'].every(nm=>r2.ingredients.some(i=>i.name===nm)));
let r5=E.calcRecipe({categoryId:'grill',foodWeightG:300,stylePresetId:'gordon_ramsay',intensity:'normal'});
console.log('  T5 고든램지: 단맛프로필<=1='+(r5.taste.sweet<=1)+' 다시다없음='+(!r5.ingredients.some(i=>i.name==='다시다')));
console.log('\n=== 탐색 기성품 조합 (유명 제품) ===');
console.log('  '+E.PRODUCT_COMBOS.slice(0,7).map(c=>c.name).join(' / '));
console.log('  COND에 다시다='+!!E.COND.dasida+', 연두='+!!E.COND.yeondu+', 미원='+!!E.COND.miwon+', 쯔유='+!!E.COND.tsuyu);
EOF
