input.new_string:
function spoonStr(g, density){
  const ml = g / (density || 1.0);
  if (ml < 2.5) return "약간";
  let tsp = round05(ml/5);              // 작은술(5ml) 단위로 반올림
  let tbsp = Math.floor(tsp/3);         // 1큰술 = 3작은술(15ml)
  let rem = round05(tsp - tbsp*3);
  if (rem >= 3){ tbsp += 1; rem -= 3; }
  const p = [];
  if (tbsp > 0) p.push(tbsp + "큰술");
  if (rem > 0) p.push(fmtNum(rem) + "작은술");
  return p.length ? p.join(" ") : "약간";
}

