    let g=(it.ax && s.base[it.ax]>0) ? it.g*(sauceState[it.ax]/s.base[it.ax]) : it.g; g=Math.max(0,g);
    const dim=g<0.5; const spoon=dim?"":spoonStr(g, SAUCE_DENS[it.n]||1.1);
    return `<div class="ing${dim?' sub':''}"><div class="l"><span class="cdot" style="background:${it.ax?sauceColor(it.ax):'#9C9484'}"></span><div><div class="nm">${it.n}</div></div></div>
      <div class="r">${dim?'<div class="sp">빼기</div>':`<div class="g">${fmtG(g)}<small>g</small></div><div class="sp">🥄 ${spoon}</div>`}</div></div>`;
  }).join("");
  $("sauceRecipe").innerHTML=`<div class="rcard hero"><h3>🥫 ${s.name} 소스 <span class="heronote">— 2인분 기준</span></h3>${rows}</div>
    <div class="rcard"><div class="rsummary">위 조절좌(맵기·단맛 등)를 움직이면 재료 양이 <b>실시간</b>으로 바뀌어요. 맵기 0으로 내리면 매운 재료는 '빼기'!</div></div>`;
}
selectSauce(SAUCES[0]);

