cat > _t.mjs <<'EOF'
import fs from 'fs';
const html=fs.readFileSync('요똥을_위한_전자혀.html','utf8');
const body=html.split('<script>')[1].split('</script>')[0];
// SAUCES 배열만 추출해 스케일 로직 검증
const i=body.indexOf('const SAUCES=['); const j=body.indexOf('];', i)+2;
const block=body.slice(i,j).replace('const SAUCES=','globalThis.SAUCES=');
(0,eval)(block);
function scaled(s, state){ return s.ing.map(it=>{ let g=(it.ax&&s.base[it.ax]>0)?it.g*(state[it.ax]/s.base[it.ax]):it.g; g=Math.max(0,g); return it.n+' '+(g<0.5?'빼기':g.toFixed(1)+'g'); }); }
const buldak=SAUCES.find(s=>s.name==='불닭볶음');
console.log('총 소스:', SAUCES.length, '종 →', SAUCES.map(s=>s.name).join(', '));
console.log('\n[불닭볶음] 기본(매움10):', scaled(buldak, buldak.base).join(', '));
console.log('[불닭볶음] 매움5로 ↓ :', scaled(buldak, {...buldak.base, spicy:5}).join(', '));
console.log('[불닭볶음] 매움0(빼기):', scaled(buldak, {...buldak.base, spicy:0}).join(', '));
const honey=SAUCES.find(s=>s.name==='허니콤보');
console.log('\n[허니콤보] 기본(단맛8):', scaled(honey, honey.base).join(', '));
console.log('[허니콤보] 단맛10으로↑:', scaled(honey, {...honey.base, sweet:10}).join(', '));
EOF
node _t.mjs; rm -f _t.mjs

