function renderSaved(){
  const arr=loadSaved();
  if(!arr.length){ $("savedList").innerHTML=`<div class="empty">아직 저장한 레시피가 없어요.<br>계산 탭에서 배합을 만들고 💾 저장을 눌러보세요.</div>`; return; }
  $("savedList").innerHTML=arr.map((s,idx)=>{
    const ing=s.ingredients.map(i=>`${i.name} ${fmtG(i.amountG)}g (≈${i.spoon})`).join(" · ");
    const stars=[1,2,3,4,5].map(n=>`<span class="${n<=s.rating?'on':''}" data-r="${n}">★</span>`).join("");
    return `<div class="srow" data-i="${idx}">
      <div class="st"><span class="stt">${s.title}</span><span class="sd">${s.createdAt}</span></div>
      <div class="sm">${s.foodWeightG}g · ${s.categoryName} · ${s.styleName}${s.zon!=null?` · <span style="color:${s.zon>=78?'var(--gold)':'var(--muted)'}">존맛 ${s.zon}${s.zon>=78?'★':''}</span>`:''}</div>
      <div class="stars" data-i="${idx}">${stars}</div>
      <div class="sing">${ing}</div>
      <div class="act"><button class="toggle">재료 보기</button><button class="del" data-i="${idx}">삭제</button></div>
    </div>`;
  }).join("");
  $("savedList").querySelectorAll(".srow").forEach(row=>{
    row.querySelector(".toggle").onclick=()=>row.classList.toggle("open");
    row.querySelector(".del").onclick=()=>{ const arr2=loadSaved(); arr2.splice(+row.dataset.i,1); writeSaved(arr2); renderSaved(); };
    row.querySelector(".stars").onclick=e=>{ const s=e.target.closest("[data-r]"); if(!s)return; const arr2=loadSaved(); arr2[+row.dataset.i].rating=+s.dataset.r; writeSaved(arr2); renderSaved(); };
  });
}

