const RECIPES=[
  {emoji:"🍙",name:"김밥",diff:"★★☆",time:"25분",
   ing:["밥 1.5공기","김밥김 2장","단무지 2줄","맛살 2개","계란 2개","당근·시금치 약간","참기름 1작은술","소금·통깨"],
   steps:["따뜻한 밥에 참기름 1작은술·소금 약간·깨를 살살 섞어 한 김 식힌다.","계란은 도톰하게 부쳐 길게 썰고, 당근채는 소금 간해 볶고, 시금치는 데쳐 참기름·소금에 무친다.","김 위에 밥을 2/3만 얇게 펴고 속재료를 가지런히 올린다.","끝에서부터 단단히 말고, 칼에 참기름을 발라 한입 크기로 썬다."],
