  const arr=loadFridge(); arr.push({name, bought:($("frDate").value||frToday()), days:parseInt($("frDays").value)||7}); saveFridge(arr);
  $("frName").value=""; renderFridge();
}
function renderFridge(){
  const el=$("frList"); if(!el) return;
  const arr=loadFridge().map((x,i)=>{ const ub=frUseby(x); return {...x,i,ub,dd:frDday(ub)}; }).sort((a,b)=>a.dd-b.dd);
  if(!arr.length){ el.innerHTML=`<div class="empty" style="padding:30px 20px">냉장고에 산 재료를 추가해보세요.<br>산 날짜로 '언제까지 써야 하는지' 자동 계산돼요 🧊</div>`; return; }
