  el.innerHTML=banner+arr.map(x=>{
    const cls=x.dd<0?"exp":x.dd<=2?"soon":"";
    const dt=x.dd<0?`만료 +${-x.dd}일`:x.dd===0?"오늘까지":`D-${x.dd}`;
    return `<div class="fritem ${cls}"><div class="fl"><div class="fn">${x.name}</div><div class="fmeta">${x.bought} 구입 · ~${x.ub}까지</div></div><div class="frr"><span class="fdday">${dt}</span><button class="frdel" data-i="${x.i}" aria-label="삭제">×</button></div></div>`;
  }).join("");
  el.querySelectorAll(".frdel").forEach(b=>b.onclick=()=>{ const a=loadFridge(); a.splice(+b.dataset.i,1); saveFridge(a); renderFridge(); });
