.fritem .frdel{background:none;border:none;color:var(--faint);font-size:18px;cursor:pointer;line-height:1;padding:0 2px}
.frpaste{margin:2px 16px 6px;border:1px solid var(--border);border-radius:11px;background:var(--surface);overflow:hidden}
.frpaste summary{padding:11px 13px;font-size:12.5px;font-weight:700;color:var(--text);cursor:pointer;list-style:none}
.frpaste summary::-webkit-details-marker{display:none}
.frpaste[open] summary{border-bottom:1px solid var(--border)}
.frpaste textarea{display:block;width:100%;box-sizing:border-box;min-height:96px;border:none;background:transparent;color:var(--text);font-family:var(--body);font-size:13px;line-height:1.5;padding:11px 13px;resize:vertical;outline:none}
.frpaste #frPasteBtn{margin:0 13px 12px;font-weight:700;font-size:13px;color:#1a130c;background:var(--accent);border:none;border-radius:10px;padding:9px 18px;cursor:pointer}

